queries.sql:
SELECT SalesID, Sum(BilledQuantity) AS BilledQty
FROM S_InvoiceSource
GROUP BY SalesID;

SELECT s.*, s.Quantity-IIf(b.BilledQty Is Null,0,b.BilledQty)-IIf(r.ReturnedQty Is Null,0,r.ReturnedQty) AS AvailableQuantity
FROM (T_売上台帳 AS s LEFT JOIN CQ_Billed AS b ON s.sumi=b.SalesID) LEFT JOIN CQ_UnbilledReturn AS r ON s.sumi=r.SalesID
WHERE s.Quantity>0;

SELECT d.SalesID, Sum(r.UnbilledQuantity) AS ReturnedQty
FROM S_Return AS r INNER JOIN S_DeliveryLine AS d ON r.DeliveryLineID=d.DeliveryLineID
GROUP BY d.SalesID;

SELECT *
FROM J_Run
ORDER BY StartedAt DESC;

SELECT InvoiceID, Sum(Amount) AS AllocatedAmount
FROM S_Allocation
GROUP BY InvoiceID;

SELECT PaymentID, Sum(Amount) AS AllocatedAmount
FROM S_Allocation
GROUP BY PaymentID;

SELECT p.PaymentID, p.ClientID, p.PaidAt, p.Amount, p.Amount-IIf(a.AllocatedAmount Is Null,0,a.AllocatedAmount) AS UnallocatedAmount
FROM S_Payment AS p LEFT JOIN JQ_入金消込合計 AS a ON p.PaymentID=a.PaymentID
WHERE p.Amount-IIf(a.AllocatedAmount Is Null,0,a.AllocatedAmount)<>0;

SELECT *
FROM SQ_請求残
WHERE OutstandingAmount<>0;

SELECT OrderID AS 受注ID, ClientID AS 得意先ID, OrderLineID AS 受注明細ID, ProductName AS 商品名, Quantity AS 受注数, DeliveredQuantity AS 納品数, CancelledQuantity AS 取消数, RemainingQuantity AS 受注残数, RemainingQuantity*UnitPrice AS 受注残金額
FROM SQ_受注明細状況
WHERE RemainingQuantity>0;

SELECT OrderLineID, Sum(Quantity) AS TotalDelivered
FROM S_DeliveryLine
GROUP BY OrderLineID;

SELECT DeliveryLineID, Sum(Quantity) AS ReturnedQuantity
FROM S_Return
GROUP BY DeliveryLineID;

SELECT InvoiceID, Sum(CreditAmount) AS TotalCredit
FROM S_ReturnAllocation
GROUP BY InvoiceID;

SELECT sumi AS 売上ID, ClientID AS 得意先ID, SalesDate AS 売上日, ProductName AS 商品名, AvailableQuantity AS 未請求数量, UnitPrice AS 単価, AvailableQuantity*UnitPrice AS 税抜金額
FROM CQ_Unbilled
WHERE AvailableQuantity>0 AND sumi IN (SELECT SalesID FROM S_SaleMeta WHERE Status='計上');
